from __future__ import annotations

import sys
from pathlib import Path

import pytest

# the app has no package install: import it from its folder
APP_DIR = Path(__file__).resolve().parents[3] / "services" / "ui"
sys.path.insert(0, str(APP_DIR))

from ui.tool_forms import ToolRequest, schema_fields  # noqa: E402
from ui.widgets import (  # noqa: E402  # after the sys.path line above
    TOOL_FORMS,
    form_by_key,
    form_for,
)

FORMS = pytest.mark.parametrize("form", TOOL_FORMS, ids=lambda form: form.key)


@FORMS
def test_fields_are_the_tools_parameters(form):
    parameters = list(form.schema["properties"])
    assert set(form.hide) <= set(parameters), "hide names a parameter the tool doesn't have"
    assert [field.name for field in form.fields({})] == [name for name in parameters if name not in form.hide]


@FORMS
def test_form_is_found_by_key_and_for_a_request(form):
    assert isinstance(form.result_type, type)
    assert form_by_key(form.key) is form
    assert form_for(ToolRequest(form.key)) is form


@FORMS
def test_defaults_pass_the_tools_validator(form):
    # an untouched form, as the browser submits it, is valid arguments for the tool
    submitted = {
        field.name: field.value for field in form.fields({}) if not (field.kind == "check" and not field.value)
    }
    arguments = form.arguments(submitted)
    assert set(arguments) == set(form.schema["properties"])


def test_match_videos_form():
    form = form_by_key("find_match_videos")
    fields = {
        field.name: field for field in form.fields({"char_1": "little_mac", "region": "NA", "players_are_tags": True})
    }
    assert "page" not in fields
    assert fields["char_1"].value == "little_mac"
    assert (fields["region"].kind, fields["region"].options, fields["region"].value) == (
        "select",
        ["", "Japan", "NA", "EU", "Other"],
        "NA",
    )
    assert (fields["players_are_tags"].kind, fields["players_are_tags"].value) == ("check", "on")
    assert fields["player_1"].help  # the description the model reads


def test_arguments_are_validated_like_the_models():
    form = form_by_key("find_match_videos")
    arguments = form.arguments({"char_1": " cloud ", "region": "EU"})
    assert (arguments["char_1"], arguments["region"], arguments["page"], arguments["players_are_tags"]) == (
        "cloud",
        "EU",
        1,
        False,
    )
    with pytest.raises(ValueError, match="region"):
        form.arguments({"region": "Mars"})


def test_schema_fields_kinds():
    schema = {
        "properties": {
            "name": {"type": "string", "default": "x", "description": "a\nname"},
            "count": {"type": "integer", "default": 3},
            "flag": {"type": "boolean", "default": False},
            "side": {"enum": ["left", "right"], "type": "string"},
            "skip": {"type": "string"},
        }
    }
    fields = schema_fields(schema, {"count": 5}, hide=("skip",))
    assert [(f.name, f.kind, f.value) for f in fields] == [
        ("name", "text", "x"),
        ("count", "number", "5"),
        ("flag", "check", ""),
        ("side", "select", ""),
    ]
    assert fields[0].help == "a name"
    assert fields[3].options == ["left", "right"]


def test_agents_original_call_can_be_put_back(monkeypatch):
    # session.py imports the app's render code (reflex); skip where that isn't installed
    pytest.importorskip("reflex")
    # importing the app links its editor assets into ./assets: keep that in the app's folder
    monkeypatch.chdir(APP_DIR)
    from ds.data.raw.smashtube import MatchVideos, VideoQuery
    from ui.session import Session

    def videos(tag: str) -> MatchVideos:
        return MatchVideos(query=VideoQuery(player_1=tag), total="1", page=1, pages=1, videos=[], source_url="")

    session = Session()
    original = videos("a")
    name = session.bind_result(original, "find_match_videos", {"player_1": "a"})
    slot = f"tab:{name}"
    assert not session.show(slot).form_changed
    assert not session.restore_original(slot)  # nothing to put back yet

    session.put(slot, videos("b"), {"player_1": "b"})  # the form is re-run
    session.put(slot, videos("b"))  # ... then paged: same call
    shown = session.show(slot)
    assert (shown.form[0].value, shown.form_changed) == ("b", True)

    assert session.restore_original(slot)
    shown = session.show(slot)
    assert session.namespace[name] is original
    assert (shown.form[0].value, shown.form_changed) == ("a", False)

    # a form added by hand has no original
    by_hand = session.bind_result(videos(""), "find_match_videos")
    session.put(f"tab:{by_hand}", videos("c"), {"player_1": "c"})
    assert not session.show(f"tab:{by_hand}").form_changed
